window.addEventListener("load",function(){document.querySelectorAll(".highlightjs").forEach(function(e){Array.from(e.getElementsByTagName("*")).reverse().forEach(function(e){var a=e.innerHTML.replaceAll(/ \(([1-9]|1[0-9]|20)\)$/gm,' <i class="conum" data-value="$1"></i><b>($1)</b>').replaceAll(/ \(<span class="hljs-number">([1-9]|1[0-9]|20)<\/span>\)$/gm,' <i class="conum" data-value="$1"></i><b>($1)</b>');e.innerHTML=a})})},!0);